sys_ux_data_broker_transform.script:
function transform(input) {
    // Retrieve the system property value
    var pluginString = gs.getProperty('optional.sam.plugin'); // Replace with your actual property name

    // Parse the JSON string into an array of objects
    var pluginArray = JSON.parse(pluginString);

    // Iterate over the parsed data and create the desired output
    var pluginInfoArray = pluginArray.map(function (plugin) {
        var pluginInfo = {
            id: plugin.id,
            description: plugin.description,
            active: GlidePluginManager.isActive(plugin.id) // Check if the plugin is active
        };

        // If the plugin name starts with sn_, query the sys_store_app table for the update_available field
        if (plugin.id.startsWith('sn_')) {
            var sysStoreApp = new GlideRecord('sys_store_app');
            sysStoreApp.addQuery('scope', plugin.id);
            sysStoreApp.query();

            if (sysStoreApp.next()) {
                pluginInfo.update_available = sysStoreApp.getValue('update_available') == "1" ? "true" : "false";
				pluginInfo.current_version = sysStoreApp.getValue("version");

                // If update_available is true, look up the sys_app_version table
                if (pluginInfo.update_available === "true") {
                    var sysAppVersion = new GlideRecord('sys_app_version');
                    sysAppVersion.addQuery('scope', plugin.id); // Match the name of the plugin
                    sysAppVersion.query();

                    if (sysAppVersion.next()) {
                        pluginInfo.available_version = sysAppVersion.getValue('version'); // Retrieve the version field
                    } else {
                        pluginInfo.available_version = null; // Default to null if no record is found
                    }
                }
            } else {
                pluginInfo.update_available = "false"; // Default to false if no record is found
                pluginInfo.available_version = null;
            }
        }

        // If the plugin name starts with com., query the v_plugin table for version and available_version
        if (plugin.id.startsWith('com.')) {
            var vPlugin = new GlideRecord('v_plugin');
            vPlugin.addQuery('id', plugin.id);
            vPlugin.query();

            if (vPlugin.next()) {
                pluginInfo.current_version = vPlugin.getValue('version');
                pluginInfo.available_version = vPlugin.getValue('available_version');
            } else {
                pluginInfo.current_version = null; // Default to null if no record is found
                pluginInfo.available_version = null;
            }
        }

        return pluginInfo;
    });

    // Pass the data to the Data Broker
    var outputs = pluginInfoArray;

    // Return the output so it can be used in UI Builder or other processes
    return outputs;
}
